-- ===== 1/8 integration-delivery-foundation.sql =====
-- P1-02d: additive first-install schema, manual TEST DB apply only.
-- No existing order/shipping table, trigger, RPC or application row is modified.
-- Live execution stays blocked; these functions only claim/reserve mock work.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';

CREATE TABLE public.integration_outbox (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  provider text NOT NULL CHECK(provider IN ('resend','gemini','pgvector','cloudinary','google','ga4','search_console','merchant','pagespeed','turnstile')),
  environment text NOT NULL DEFAULT 'mock' CHECK(environment IN ('mock','staging','production')),
  dedupe_key text NOT NULL CHECK(length(dedupe_key) BETWEEN 1 AND 250),
  event_type text NOT NULL CHECK(event_type ~ '^[a-z][a-z0-9_]{0,63}$'),
  operation_kind text NOT NULL CHECK(operation_kind IN ('read','mutation')),
  payload jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(payload)='object' AND octet_length(payload::text)<=65536),
  state text NOT NULL DEFAULT 'QUEUED' CHECK(state IN ('QUEUED','WORKING','ACCEPTED','DELIVERED','UNKNOWN','DEAD')),
  attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 8),
  version integer NOT NULL DEFAULT 1 CHECK(version>0),
  lease_token uuid,
  lease_until timestamptz,
  next_at timestamptz NOT NULL DEFAULT now(),
  provider_message_id text CHECK(length(provider_message_id)<=250),
  last_error_code text CHECK(last_error_code ~ '^[A-Z][A-Z0-9_]{0,63}$'),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(provider,environment,dedupe_key),
  CHECK((state='WORKING')=(lease_token IS NOT NULL AND lease_until IS NOT NULL)),
  CHECK((lease_token IS NULL)=(lease_until IS NULL))
);
CREATE INDEX integration_outbox_due ON public.integration_outbox(provider,environment,state,next_at);
CREATE INDEX integration_outbox_expired ON public.integration_outbox(lease_until) WHERE state='WORKING';

CREATE TABLE public.integration_usage_daily (
  provider text NOT NULL CHECK(provider IN ('resend','gemini','pgvector','cloudinary','google','ga4','search_console','merchant','pagespeed','turnstile')),
  environment text NOT NULL CHECK(environment IN ('mock','staging','production')),
  day date NOT NULL,
  metric text NOT NULL CHECK(metric IN ('requests','tokens','emails','milli_credits')),
  used bigint NOT NULL DEFAULT 0 CHECK(used>=0),
  hard_limit bigint NOT NULL DEFAULT 0 CHECK(hard_limit BETWEEN 0 AND 1000000000000),
  warned_thresholds integer[] NOT NULL DEFAULT '{}'::integer[],
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(provider,environment,day,metric),
  CHECK(used<=hard_limit)
);

ALTER TABLE public.integration_outbox ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.integration_usage_daily ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.integration_outbox,public.integration_usage_daily FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.integration_outbox,public.integration_usage_daily TO service_role;

CREATE FUNCTION public.integration_claim(p_provider text,p_environment text,p_limit integer DEFAULT 10,p_lease_seconds integer DEFAULT 120)
RETURNS SETOF public.integration_outbox
LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
DECLARE v_now timestamptz:=clock_timestamp();
BEGIN
  IF p_environment IS DISTINCT FROM 'mock' THEN RAISE EXCEPTION 'LIVE_INTEGRATION_BLOCKED' USING ERRCODE='42501'; END IF;
  IF p_provider IS NULL OR p_provider NOT IN ('resend','gemini','pgvector','cloudinary','google','ga4','search_console','merchant','pagespeed','turnstile')
    OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 20 OR p_lease_seconds IS NULL OR p_lease_seconds NOT BETWEEN 5 AND 300
  THEN RAISE EXCEPTION 'INVALID_INTEGRATION_CLAIM' USING ERRCODE='22023'; END IF;
  -- Recovery is bounded too. A lost mutation lease has an ambiguous outcome,
  -- so it must never be put back on an automatic send queue.
  WITH expired AS (
    SELECT id FROM public.integration_outbox
    WHERE provider=p_provider AND environment=p_environment AND state='WORKING' AND lease_until<=v_now
    ORDER BY lease_until,id LIMIT 20 FOR UPDATE SKIP LOCKED
  )
  UPDATE public.integration_outbox o SET
    state=CASE WHEN operation_kind='mutation' THEN 'UNKNOWN' WHEN attempts>=8 THEN 'DEAD' ELSE 'QUEUED' END,
    lease_token=NULL,lease_until=NULL,version=version+1,updated_at=v_now,next_at=v_now,
    last_error_code='LEASE_EXPIRED'
  FROM expired e WHERE o.id=e.id;
  RETURN QUERY
  WITH candidates AS (
    SELECT id FROM public.integration_outbox
    WHERE provider=p_provider AND environment=p_environment AND state='QUEUED' AND attempts<8 AND next_at<=v_now
    ORDER BY next_at,id LIMIT p_limit FOR UPDATE SKIP LOCKED
  )
  UPDATE public.integration_outbox o SET
    state='WORKING',attempts=attempts+1,version=version+1,
    lease_token=gen_random_uuid(),lease_until=v_now+make_interval(secs=>p_lease_seconds),updated_at=v_now
  FROM candidates c WHERE o.id=c.id RETURNING o.*;
END;
$$;

CREATE FUNCTION public.integration_finish(p_id uuid,p_lease_token uuid,p_version integer,p_outcome text,p_provider_message_id text DEFAULT NULL,p_error_code text DEFAULT NULL)
RETURNS public.integration_outbox
LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
DECLARE r public.integration_outbox; v_now timestamptz:=clock_timestamp(); v_state text;
BEGIN
  IF p_outcome IS NULL OR p_outcome NOT IN ('ACCEPTED','RETRY','UNKNOWN','DEAD')
    OR length(p_provider_message_id)>250 OR (p_error_code IS NOT NULL AND p_error_code !~ '^[A-Z][A-Z0-9_]{0,63}$')
  THEN RAISE EXCEPTION 'INVALID_INTEGRATION_OUTCOME' USING ERRCODE='22023'; END IF;
  SELECT * INTO r FROM public.integration_outbox WHERE id=p_id FOR UPDATE;
  IF NOT FOUND OR r.state<>'WORKING' OR r.lease_token IS DISTINCT FROM p_lease_token
    OR r.version IS DISTINCT FROM p_version OR r.lease_until<=v_now
  THEN RAISE EXCEPTION 'INTEGRATION_LEASE_CONFLICT' USING ERRCODE='PT409'; END IF;
  IF r.environment<>'mock' THEN RAISE EXCEPTION 'LIVE_INTEGRATION_BLOCKED' USING ERRCODE='42501'; END IF;
  IF r.operation_kind='mutation' AND p_outcome='RETRY'
  THEN RAISE EXCEPTION 'MUTATION_RETRY_FORBIDDEN' USING ERRCODE='22023'; END IF;
  v_state=CASE WHEN p_outcome='RETRY' THEN CASE WHEN r.attempts>=8 THEN 'DEAD' ELSE 'QUEUED' END ELSE p_outcome END;
  UPDATE public.integration_outbox SET state=v_state,lease_token=NULL,lease_until=NULL,
    provider_message_id=p_provider_message_id,last_error_code=p_error_code,version=version+1,updated_at=v_now,
    next_at=CASE WHEN v_state='QUEUED' THEN v_now+make_interval(secs=>least(3600,power(2,r.attempts)::integer)) ELSE next_at END
  WHERE id=r.id RETURNING * INTO r;
  RETURN r;
END;
$$;

CREATE FUNCTION public.integration_reserve_usage(p_provider text,p_environment text,p_metric text,p_amount bigint,p_hard_limit bigint)
RETURNS jsonb
LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
DECLARE r public.integration_usage_daily; v_day date:=(clock_timestamp() AT TIME ZONE 'UTC')::date; crossed integer[];
BEGIN
  IF p_environment IS DISTINCT FROM 'mock' THEN RAISE EXCEPTION 'LIVE_INTEGRATION_BLOCKED' USING ERRCODE='42501'; END IF;
  IF p_amount IS NULL OR p_amount NOT BETWEEN 1 AND 1000000000000 OR p_hard_limit IS NULL OR p_hard_limit NOT BETWEEN 0 AND 1000000000000
  THEN RAISE EXCEPTION 'INVALID_INTEGRATION_USAGE' USING ERRCODE='22023'; END IF;
  INSERT INTO public.integration_usage_daily(provider,environment,day,metric,hard_limit)
  VALUES(p_provider,p_environment,v_day,p_metric,p_hard_limit) ON CONFLICT DO NOTHING;
  SELECT * INTO r FROM public.integration_usage_daily
  WHERE provider=p_provider AND environment=p_environment AND day=v_day AND metric=p_metric FOR UPDATE;
  IF r.hard_limit<>p_hard_limit THEN RAISE EXCEPTION 'QUOTA_POLICY_CHANGED' USING ERRCODE='PT409'; END IF;
  IF p_amount>r.hard_limit-r.used THEN RAISE EXCEPTION 'INTEGRATION_QUOTA_EXCEEDED' USING ERRCODE='PT429'; END IF;
  SELECT coalesce(array_agg(t ORDER BY t),'{}'::integer[]) INTO crossed FROM unnest(ARRAY[60,80,95]) t
  WHERE (r.used+p_amount)*100>=r.hard_limit*t AND NOT(t=ANY(r.warned_thresholds));
  UPDATE public.integration_usage_daily SET used=used+p_amount,warned_thresholds=warned_thresholds||crossed,updated_at=clock_timestamp()
  WHERE provider=p_provider AND environment=p_environment AND day=v_day AND metric=p_metric RETURNING * INTO r;
  RETURN jsonb_build_object('used',r.used,'hardLimit',r.hard_limit,'newlyCrossed',crossed,'day',r.day,'source','mock');
END;
$$;

REVOKE ALL ON FUNCTION public.integration_claim(text,text,integer,integer) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.integration_finish(uuid,uuid,integer,text,text,text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.integration_reserve_usage(text,text,text,bigint,bigint) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.integration_claim(text,text,integer,integer) TO service_role;
GRANT EXECUTE ON FUNCTION public.integration_finish(uuid,uuid,integer,text,text,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.integration_reserve_usage(text,text,text,bigint,bigint) TO service_role;
COMMIT;

-- ===== 2/8 integration-purchase-capture.sql =====
-- P2-01b. Manual TEST DB install only, after integration-delivery-foundation.sql.
-- No orders writes/triggers or external calls. RPC always records MOCK data.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';

CREATE UNIQUE INDEX integration_purchase_mock_payment_unique
ON public.integration_outbox(provider,environment,provider_message_id)
WHERE provider='ga4' AND environment='mock' AND event_type='purchase' AND provider_message_id IS NOT NULL;

CREATE FUNCTION public.integration_record_purchase_mock(p_order_id uuid,p_actor_id uuid,p_consent boolean)
RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,public SET lock_timeout='2s' AS $$
DECLARE
  o public.orders; old public.integration_outbox; row_item jsonb;
  v_items jsonb:='[]'::jsonb; v_payload jsonb; v_key text; v_tx text; v_payment text;
  v_sub numeric:=0; v_price numeric; v_qty integer; v_shipping numeric;
  v_total numeric; v_discount numeric; v_net numeric; v_prefix numeric:=0;
  v_previous numeric:=0; v_line numeric; v_unit numeric; v_rest integer;
  v_product text; v_variant text; v_base jsonb; v_id uuid;
BEGIN
  IF p_order_id IS NULL OR p_actor_id IS NULL OR p_consent IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'PURCHASE_CONSENT_REQUIRED' USING ERRCODE='22023'; END IF;
  SELECT * INTO o FROM public.orders WHERE id=p_order_id AND user_id=p_actor_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'PURCHASE_NOT_FOUND' USING ERRCODE='PT404'; END IF;
  IF o.payment_status IS DISTINCT FROM 'paid' OR o.payment_method IS DISTINCT FROM 'sepay'
    OR o.status IS NULL OR o.status NOT IN ('PAID','SHIPPED','COMPLETED')
    OR nullif(btrim(o.transaction_code),'') IS NULL
  THEN RETURN jsonb_build_object('source','mock','status','not_eligible'); END IF;
  IF jsonb_typeof(o.items) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'INVALID_PURCHASE_SNAPSHOT' USING ERRCODE='PT422'; END IF;
  IF jsonb_array_length(o.items) NOT BETWEEN 1 AND 100
    OR jsonb_typeof(o.shipping_info->'shipping_fee') IS DISTINCT FROM 'number'
    OR o.total IS NULL OR o.voucher_discount_amount IS NULL
  THEN RAISE EXCEPTION 'INVALID_PURCHASE_SNAPSHOT' USING ERRCODE='PT422'; END IF;
  v_total:=o.total*100; v_discount:=o.voucher_discount_amount*100;
  v_shipping:=(o.shipping_info->>'shipping_fee')::numeric*100;
  IF v_total NOT BETWEEN 0 AND 100000000000000 OR v_total<>trunc(v_total)
    OR v_discount NOT BETWEEN 0 AND 100000000000000 OR v_discount<>trunc(v_discount)
    OR v_shipping NOT BETWEEN 0 AND 100000000000000 OR v_shipping<>trunc(v_shipping)
  THEN RAISE EXCEPTION 'INVALID_PURCHASE_SNAPSHOT' USING ERRCODE='PT422'; END IF;
  FOR row_item IN SELECT value FROM jsonb_array_elements(o.items) LOOP
    IF jsonb_typeof(row_item->'price') IS DISTINCT FROM 'number'
      OR jsonb_typeof(row_item->'quantity') IS DISTINCT FROM 'number'
      OR (row_item->>'quantity')::numeric NOT BETWEEN 1 AND 999
      OR (row_item->>'quantity')::numeric<>trunc((row_item->>'quantity')::numeric)
    THEN RAISE EXCEPTION 'INVALID_PURCHASE_SNAPSHOT' USING ERRCODE='PT422'; END IF;
    v_price:=(row_item->>'price')::numeric*100; v_qty:=(row_item->>'quantity')::numeric::integer;
    IF v_price NOT BETWEEN 0 AND 100000000000000 OR v_price<>trunc(v_price)
    THEN RAISE EXCEPTION 'INVALID_PURCHASE_SNAPSHOT' USING ERRCODE='PT422'; END IF;
    v_product:=coalesce(row_item->>'productId',row_item->>'product_id');
    v_variant:=coalesce(row_item->>'variantId',row_item->>'variant_id');
    IF v_product IS NULL OR v_product !~* '^([a-f0-9]{8}-([a-f0-9]{4}-){3}[a-f0-9]{12}|[a-z][a-z0-9_-]{0,63})$'
      OR (v_variant IS NOT NULL AND v_variant !~* '^([a-f0-9]{8}-([a-f0-9]{4}-){3}[a-f0-9]{12}|[a-z][a-z0-9_-]{0,63})$')
    THEN RAISE EXCEPTION 'INVALID_PURCHASE_SNAPSHOT' USING ERRCODE='PT422'; END IF;
    v_sub:=v_sub+v_price*v_qty;
  END LOOP;
  v_net:=v_total-v_shipping;
  IF v_net<0 OR v_discount>v_sub OR v_net<>v_sub-v_discount
  THEN RAISE EXCEPTION 'INVALID_PURCHASE_SNAPSHOT' USING ERRCODE='PT422'; END IF;

  FOR row_item IN SELECT value FROM jsonb_array_elements(o.items) LOOP
    v_price:=(row_item->>'price')::numeric*100; v_qty:=(row_item->>'quantity')::numeric::integer;
    v_prefix:=v_prefix+v_price*v_qty;
    v_line:=CASE WHEN v_sub=0 THEN 0 ELSE floor(v_net*v_prefix/v_sub) END-v_previous;
    v_previous:=v_previous+v_line;
    v_unit:=floor(v_line/v_qty); v_rest:=mod(v_line,v_qty)::integer;
    v_base:=jsonb_build_object('item_id',coalesce(row_item->>'productId',row_item->>'product_id'));
    v_variant:=coalesce(row_item->>'variantId',row_item->>'variant_id');
    IF v_variant IS NOT NULL THEN v_base:=v_base||jsonb_build_object('item_variant',v_variant); END IF;
    IF v_rest>0 THEN
      v_items:=v_items||jsonb_build_array(v_base||jsonb_build_object('price',(v_unit+1)/100,'quantity',v_rest));
    END IF;
    IF v_qty>v_rest THEN
      v_items:=v_items||jsonb_build_array(v_base||jsonb_build_object('price',v_unit/100,'quantity',v_qty-v_rest));
    END IF;
  END LOOP;
  v_tx:='gp_mock_v1_'||encode(sha256(convert_to('ga4:purchase:v1:'||p_order_id::text,'UTF8')),'hex');
  v_payment:='sp_'||encode(sha256(convert_to('sepay:payment:v1:'||btrim(o.transaction_code),'UTF8')),'hex');
  v_key:='purchase_v1:'||v_tx;
  v_payload:=jsonb_build_object('transaction_id',v_tx,'currency','VND','value',v_net/100,
    'shipping',v_shipping/100,'tax',0,'items',v_items);
  SELECT * INTO old FROM public.integration_outbox WHERE provider='ga4' AND environment='mock' AND dedupe_key=v_key;
  IF FOUND THEN
    IF old.event_type<>'purchase' OR old.state<>'ACCEPTED' OR old.payload IS DISTINCT FROM v_payload OR old.provider_message_id IS DISTINCT FROM v_payment OR old.operation_kind<>'mutation'
    THEN RAISE EXCEPTION 'PURCHASE_CONFLICT' USING ERRCODE='PT409'; END IF;
    RETURN jsonb_build_object('source','mock','status','duplicate','transactionId',v_tx);
  END IF;
  BEGIN
    INSERT INTO public.integration_outbox(provider,environment,dedupe_key,event_type,operation_kind,payload,state,attempts,provider_message_id)
    VALUES('ga4','mock',v_key,'purchase','mutation',v_payload,'ACCEPTED',1,v_payment) RETURNING id INTO v_id;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'PURCHASE_CONFLICT' USING ERRCODE='PT409';
  END;
  PERFORM public.integration_reserve_usage('ga4','mock','requests',1,100);
  RETURN jsonb_build_object('source','mock','status','recorded','transactionId',v_tx);
END;
$$;
REVOKE ALL ON FUNCTION public.integration_record_purchase_mock(uuid,uuid,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.integration_record_purchase_mock(uuid,uuid,boolean) TO service_role;
COMMIT;

-- ===== 3/8 integration-notifications.sql =====
-- P4-02a first install on TEST DB after integration-delivery-foundation.sql.
-- No order write/trigger or live transport. Atomic committed-snapshot capture.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';

CREATE FUNCTION public.integration_notification_source_mock(p_order_id uuid,p_event text)
RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
DECLARE o public.orders; v_to text; v_status text; v_subject text; v_template text;
  v_context jsonb; v_items jsonb; v_payment text:=''; v_mail jsonb;
BEGIN
  IF p_order_id IS NULL OR p_event IS NULL OR p_event NOT IN ('order_confirmation','payment_success','order_status')
  THEN RAISE EXCEPTION 'NOTIFICATION_INVALID_SOURCE' USING ERRCODE='22023'; END IF;
  SELECT * INTO o FROM public.orders WHERE id=p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOTIFICATION_NOT_FOUND' USING ERRCODE='PT404'; END IF;
  IF o.status IS NULL OR o.status NOT IN ('PENDING','AWAITING_PAYMENT','PAID','SHIPPED','COMPLETED','CANCELED','EXPIRED')
    OR (p_event='order_confirmation' AND o.status IN ('CANCELED','EXPIRED'))
    OR (p_event='payment_success' AND (o.payment_status IS DISTINCT FROM 'paid' OR o.payment_method IS DISTINCT FROM 'sepay'
      OR nullif(btrim(o.transaction_code),'') IS NULL OR o.status NOT IN ('PAID','SHIPPED','COMPLETED')))
  THEN RETURN jsonb_build_object('source','mock','eligible',false); END IF;
  v_to:=lower(btrim(o.shipping_info->>'email'));
  IF v_to IS NULL OR length(v_to)>254 OR v_to !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
    OR o.total IS NULL OR o.total NOT BETWEEN 0 AND 1000000000000 OR o.total*100<>trunc(o.total*100)
    OR jsonb_typeof(o.items) IS DISTINCT FROM 'array'
  THEN RAISE EXCEPTION 'NOTIFICATION_SNAPSHOT_INVALID' USING ERRCODE='PT422'; END IF;
  IF jsonb_array_length(o.items) NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'NOTIFICATION_SNAPSHOT_INVALID' USING ERRCODE='PT422'; END IF;
  SELECT jsonb_agg(jsonb_build_object('title',left(coalesce(item->>'title',''),300),
    'price',item->'price','quantity',item->'quantity') ORDER BY ordinal) INTO v_items
    FROM jsonb_array_elements(o.items) WITH ORDINALITY x(item,ordinal);
  v_context:=jsonb_build_object('id',o.id,'total',o.total);
  IF p_event='payment_success' THEN
    v_status:='paid'; v_subject:='Payment Received for Order #'||o.id; v_template:='payment-success';
    v_payment:=encode(sha256(convert_to(btrim(o.transaction_code),'UTF8')),'hex');
  ELSIF p_event='order_confirmation' THEN
    v_status:='created'; v_subject:='Order Confirmation #'||o.id; v_template:='order-confirmation';
    v_context:=v_context||jsonb_build_object('items',v_items);
  ELSE
    v_status:=o.status; v_template:='order-status'; v_subject:='Order #'||o.id||' Update';
    v_context:=v_context||jsonb_build_object('status',o.status,'items',v_items);
  END IF;
  v_mail:=jsonb_build_object('to',v_to,'subject',v_subject,'template',v_template,'context',v_context);
  RETURN jsonb_build_object('source','mock','eligible',true,'orderId',o.id,'event',p_event,'status',v_status,
    'binding',encode(sha256(convert_to(v_mail::text||':'||v_payment,'UTF8')),'hex'),'mail',v_mail);
END;
$$;

CREATE FUNCTION public.integration_capture_notification_mock(p_order_id uuid,p_event text)
RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,public SET lock_timeout='2s' AS $$
DECLARE v_source jsonb; v_payload jsonb; v_key text; v_old public.integration_outbox; v_id uuid;
BEGIN
  PERFORM 1 FROM public.orders WHERE id=p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOTIFICATION_NOT_FOUND' USING ERRCODE='PT404'; END IF;
  v_source:=public.integration_notification_source_mock(p_order_id,p_event);
  IF (v_source->>'eligible')::boolean IS NOT TRUE THEN RETURN jsonb_build_object('source','mock','status','not_eligible'); END IF;
  v_key:='notice_v1:'||p_order_id||':'||p_event||':'||(v_source->>'status');
  v_payload:=v_source-'source'-'eligible'-'mail';
  SELECT * INTO v_old FROM public.integration_outbox WHERE provider='resend' AND environment='mock' AND dedupe_key=v_key;
  IF FOUND THEN
    IF v_old.payload IS DISTINCT FROM v_payload OR v_old.event_type IS DISTINCT FROM p_event OR v_old.operation_kind<>'mutation'
    THEN RAISE EXCEPTION 'NOTIFICATION_SOURCE_CONFLICT' USING ERRCODE='PT409'; END IF;
    RETURN jsonb_build_object('source','mock','status','duplicate','id',v_old.id,'state',v_old.state);
  END IF;
  INSERT INTO public.integration_outbox(provider,environment,dedupe_key,event_type,operation_kind,payload)
  VALUES('resend','mock',v_key,p_event,'mutation',v_payload) RETURNING id INTO v_id;
  RETURN jsonb_build_object('source','mock','status','recorded','id',v_id,'state','QUEUED');
END;
$$;

CREATE FUNCTION public.integration_resolve_notification_mock(p_id uuid,p_lease_token uuid,p_version integer)
RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
DECLARE r public.integration_outbox; v_source jsonb;
BEGIN
  SELECT * INTO r FROM public.integration_outbox WHERE id=p_id FOR UPDATE;
  IF NOT FOUND OR r.provider<>'resend' OR r.environment<>'mock' OR r.operation_kind<>'mutation'
    OR r.state<>'WORKING' OR r.lease_token IS DISTINCT FROM p_lease_token OR r.version IS DISTINCT FROM p_version
    OR r.lease_until<=clock_timestamp() OR r.event_type NOT IN ('order_confirmation','payment_success','order_status')
    OR jsonb_typeof(r.payload->'orderId') IS DISTINCT FROM 'string'
  THEN RAISE EXCEPTION 'NOTIFICATION_LEASE_CONFLICT' USING ERRCODE='PT409'; END IF;
  PERFORM 1 FROM public.orders WHERE id=(r.payload->>'orderId')::uuid FOR SHARE;
  v_source:=public.integration_notification_source_mock((r.payload->>'orderId')::uuid,r.event_type);
  IF (v_source->>'eligible')::boolean IS NOT TRUE OR r.payload IS DISTINCT FROM (v_source-'source'-'eligible'-'mail')
  THEN RAISE EXCEPTION 'NOTIFICATION_SOURCE_CHANGED' USING ERRCODE='PT409'; END IF;
  RETURN jsonb_build_object('source','mock','mail',v_source->'mail');
END;
$$;

REVOKE ALL ON FUNCTION public.integration_notification_source_mock(uuid,text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.integration_capture_notification_mock(uuid,text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.integration_resolve_notification_mock(uuid,uuid,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.integration_notification_source_mock(uuid,text),public.integration_capture_notification_mock(uuid,text),public.integration_resolve_notification_mock(uuid,uuid,integer) TO service_role;
COMMIT;

-- ===== 4/8 integration-merchant-queue.sql =====
-- First install on TEST DB only, after integration-delivery-foundation.sql.
-- Enqueue serialization only. No product writes, live transport or scheduler.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';
CREATE FUNCTION public.integration_enqueue_merchant_mock(p_product_id uuid,p_action text,p_fingerprint text)
RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
DECLARE r public.integration_outbox; v_generation bigint;
BEGIN
  IF p_product_id IS NULL OR p_action IS NULL OR p_action NOT IN ('upsert','withdraw')
    OR p_fingerprint IS NULL OR p_fingerprint !~ '^[a-f0-9]{64}$'
  THEN RAISE EXCEPTION 'INVALID_MERCHANT_EVENT' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('merchant:mock:'||p_product_id::text,0));
  SELECT * INTO r FROM public.integration_outbox
  WHERE provider='merchant' AND environment='mock' AND payload->>'productId'=p_product_id::text
    AND payload->>'generation' ~ '^[1-9][0-9]{0,8}$'
  ORDER BY (payload->>'generation')::bigint DESC LIMIT 1;
  IF FOUND AND r.payload->>'action'=p_action AND r.payload->>'fingerprint'=p_fingerprint THEN
    RETURN jsonb_build_object('id',r.id,'state',r.state,'status','duplicate');
  END IF;
  v_generation:=coalesce((r.payload->>'generation')::bigint,0)+1;
  IF v_generation>999999999 THEN RAISE EXCEPTION 'MERCHANT_GENERATION_LIMIT' USING ERRCODE='PT409'; END IF;
  INSERT INTO public.integration_outbox(provider,environment,dedupe_key,event_type,operation_kind,payload)
  VALUES('merchant','mock','merchant_v2:'||p_product_id::text||':'||v_generation::text,
    'catalog_'||p_action,'mutation',jsonb_build_object('productId',p_product_id,'action',p_action,
      'fingerprint',p_fingerprint,'generation',v_generation)) RETURNING * INTO r;
  RETURN jsonb_build_object('id',r.id,'state',r.state,'status','recorded');
END;
$$;
CREATE FUNCTION public.integration_merchant_is_current_mock(p_product_id uuid,p_generation bigint,p_fingerprint text)
RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,public AS $$
  SELECT coalesce((SELECT payload->>'generation'=p_generation::text AND payload->>'fingerprint'=p_fingerprint
    FROM public.integration_outbox WHERE provider='merchant' AND environment='mock'
      AND payload->>'productId'=p_product_id::text AND payload->>'generation' ~ '^[1-9][0-9]{0,8}$'
    ORDER BY (payload->>'generation')::bigint DESC LIMIT 1),false);
$$;
REVOKE ALL ON FUNCTION public.integration_enqueue_merchant_mock(uuid,text,text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.integration_merchant_is_current_mock(uuid,bigint,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.integration_enqueue_merchant_mock(uuid,text,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.integration_merchant_is_current_mock(uuid,bigint,text) TO service_role;
COMMIT;

-- ===== 5/8 integration-merchant-fence.sql =====
-- First install on TEST DB only, after integration-delivery-foundation.sql and
-- integration-merchant-queue.sql. Per-product outbound send fence for the MOCK
-- Merchant worker. No product writes, live transport, account or scheduler.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';
CREATE TABLE public.integration_merchant_send_fence (
  product_id uuid PRIMARY KEY,
  environment text NOT NULL DEFAULT 'mock' CHECK(environment='mock'),
  started_generation bigint NOT NULL DEFAULT 0 CHECK(started_generation BETWEEN 0 AND 999999999),
  accepted_generation bigint CHECK(accepted_generation BETWEEN 1 AND 999999999),
  inflight_generation bigint,
  inflight_token uuid UNIQUE,
  inflight_until timestamptz,
  last_outcome text CHECK(last_outcome IN ('ACCEPTED','UNKNOWN','REJECTED')),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK((inflight_token IS NULL)=(inflight_until IS NULL) AND (inflight_token IS NULL)=(inflight_generation IS NULL)),
  CHECK(inflight_generation IS NULL OR inflight_generation=started_generation),
  CHECK(accepted_generation IS NULL OR accepted_generation<=started_generation)
);
ALTER TABLE public.integration_merchant_send_fence ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.integration_merchant_send_fence FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.integration_merchant_send_fence TO service_role;

CREATE FUNCTION public.integration_merchant_fence_ready_mock()
RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,public AS $$ SELECT true $$;

-- Shared ownership check: caller must hold a live WORKING merchant mutation lease.
CREATE FUNCTION public.integration_merchant_owned_row_mock(p_id uuid,p_lease_token uuid,p_version integer)
RETURNS public.integration_outbox LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
DECLARE r public.integration_outbox;
BEGIN
  SELECT * INTO r FROM public.integration_outbox WHERE id=p_id FOR UPDATE;
  IF NOT FOUND OR r.provider<>'merchant' OR r.environment<>'mock' OR r.operation_kind<>'mutation'
    OR r.state<>'WORKING' OR r.lease_token IS DISTINCT FROM p_lease_token OR r.version IS DISTINCT FROM p_version
    OR r.lease_until<=clock_timestamp()
    -- coalesce: a missing key must fail the check, not yield NULL and pass.
    OR coalesce(r.payload->>'productId','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    OR coalesce(r.payload->>'generation','') !~ '^[1-9][0-9]{0,8}$'
    OR coalesce(r.payload->>'fingerprint','') !~ '^[a-f0-9]{64}$'
  THEN RAISE EXCEPTION 'MERCHANT_LEASE_CONFLICT' USING ERRCODE='PT409'; END IF;
  RETURN r;
END;
$$;

CREATE FUNCTION public.integration_merchant_begin_send_mock(p_id uuid,p_lease_token uuid,p_version integer)
RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,public SET lock_timeout='2s' AS $$
DECLARE r public.integration_outbox; f public.integration_merchant_send_fence; latest public.integration_outbox;
  v_product uuid; v_generation bigint; v_now timestamptz:=clock_timestamp();
BEGIN
  r:=public.integration_merchant_owned_row_mock(p_id,p_lease_token,p_version);
  v_product:=(r.payload->>'productId')::uuid; v_generation:=(r.payload->>'generation')::bigint;
  -- Same lock as enqueue: "latest generation" cannot change underneath us.
  PERFORM pg_advisory_xact_lock(hashtextextended('merchant:mock:'||v_product::text,0));
  SELECT * INTO latest FROM public.integration_outbox
  WHERE provider='merchant' AND environment='mock' AND payload->>'productId'=v_product::text
    AND payload->>'generation' ~ '^[1-9][0-9]{0,8}$'
  ORDER BY (payload->>'generation')::bigint DESC LIMIT 1;
  IF latest.id IS DISTINCT FROM r.id OR latest.payload->>'fingerprint' IS DISTINCT FROM r.payload->>'fingerprint' THEN
    RETURN jsonb_build_object('status','stale','generation',v_generation); END IF;
  INSERT INTO public.integration_merchant_send_fence(product_id) VALUES(v_product) ON CONFLICT DO NOTHING;
  SELECT * INTO f FROM public.integration_merchant_send_fence WHERE product_id=v_product FOR UPDATE;
  -- Monotonic: never start this generation twice nor an older one after a newer.
  IF v_generation<=f.started_generation THEN
    RETURN jsonb_build_object('status','stale','generation',v_generation); END IF;
  IF f.inflight_until>v_now THEN
    RETURN jsonb_build_object('status','busy','generation',v_generation,'inflightGeneration',f.inflight_generation); END IF;
  UPDATE public.integration_merchant_send_fence SET started_generation=v_generation,inflight_generation=v_generation,
    inflight_token=gen_random_uuid(),inflight_until=v_now+interval '60 seconds',updated_at=v_now
  WHERE product_id=v_product RETURNING * INTO f;
  RETURN jsonb_build_object('status','acquired','generation',v_generation,'fenceToken',f.inflight_token,
    'inflightUntil',f.inflight_until);
END;
$$;

CREATE FUNCTION public.integration_merchant_end_send_mock(p_fence_token uuid,p_outcome text)
RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,public SET lock_timeout='2s' AS $$
DECLARE f public.integration_merchant_send_fence;
BEGIN
  IF p_outcome IS NULL OR p_outcome NOT IN ('ACCEPTED','UNKNOWN','REJECTED') THEN
    RAISE EXCEPTION 'INVALID_MERCHANT_SEND_OUTCOME' USING ERRCODE='22023'; END IF;
  SELECT * INTO f FROM public.integration_merchant_send_fence WHERE inflight_token=p_fence_token FOR UPDATE;
  IF NOT FOUND OR p_fence_token IS NULL THEN RAISE EXCEPTION 'MERCHANT_FENCE_CONFLICT' USING ERRCODE='PT409'; END IF;
  UPDATE public.integration_merchant_send_fence SET inflight_generation=NULL,inflight_token=NULL,inflight_until=NULL,
    last_outcome=p_outcome,updated_at=clock_timestamp(),
    accepted_generation=CASE WHEN p_outcome='ACCEPTED' THEN f.inflight_generation ELSE accepted_generation END
  WHERE product_id=f.product_id;
END;
$$;

CREATE FUNCTION public.integration_merchant_defer_mock(p_id uuid,p_lease_token uuid,p_version integer)
RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,public SET lock_timeout='2s' AS $$
DECLARE r public.integration_outbox; v_started bigint; v_now timestamptz:=clock_timestamp();
BEGIN
  r:=public.integration_merchant_owned_row_mock(p_id,p_lease_token,p_version);
  SELECT started_generation INTO v_started FROM public.integration_merchant_send_fence
  WHERE product_id=(r.payload->>'productId')::uuid FOR UPDATE;
  -- Requeue is only safe with proof that this generation never started sending.
  IF coalesce(v_started,0)>=(r.payload->>'generation')::bigint THEN
    RAISE EXCEPTION 'MERCHANT_SEND_ALREADY_STARTED' USING ERRCODE='PT409'; END IF;
  UPDATE public.integration_outbox SET state='QUEUED',lease_token=NULL,lease_until=NULL,version=version+1,
    attempts=greatest(attempts-1,0),next_at=v_now+interval '30 seconds',last_error_code='SEND_FENCE_BUSY',updated_at=v_now
  WHERE id=r.id RETURNING * INTO r;
  RETURN jsonb_build_object('id',r.id,'state',r.state,'nextAt',r.next_at);
END;
$$;

REVOKE ALL ON FUNCTION public.integration_merchant_fence_ready_mock(),public.integration_merchant_owned_row_mock(uuid,uuid,integer),
  public.integration_merchant_begin_send_mock(uuid,uuid,integer),public.integration_merchant_end_send_mock(uuid,text),
  public.integration_merchant_defer_mock(uuid,uuid,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.integration_merchant_fence_ready_mock(),public.integration_merchant_owned_row_mock(uuid,uuid,integer),
  public.integration_merchant_begin_send_mock(uuid,uuid,integer),public.integration_merchant_end_send_mock(uuid,text),
  public.integration_merchant_defer_mock(uuid,uuid,integer) TO service_role;
COMMIT;

-- ===== 6/8 search-console-durable-mock.sql =====
-- First install on TEST DB. Synthetic mock property only, no Google transport.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
CREATE TABLE public.seo_search_sync_state (
  property text PRIMARY KEY DEFAULT 'sc-domain:mock.example.invalid' CHECK(property='sc-domain:mock.example.invalid'),
  source text NOT NULL DEFAULT 'mock' CHECK(source='mock'),
  version integer NOT NULL DEFAULT 0 CHECK(version>=0),
  window_dates date[] NOT NULL DEFAULT '{}'::date[] CHECK(cardinality(window_dates) IN (0,14)),
  truncated_dates date[] NOT NULL DEFAULT '{}'::date[] CHECK(cardinality(truncated_dates)<=14),
  last_synced_at timestamptz,
  last_attempt_at timestamptz,
  last_error_code text CHECK(last_error_code IN ('INVALID_RESPONSE','UNAVAILABLE','RATE_LIMITED','QUOTA_EXCEEDED','TIMEOUT','REJECTED','CIRCUIT_OPEN','CONCURRENCY_LIMIT','STORAGE_UNAVAILABLE','BLOCKED')),
  lease_token uuid,
  lease_until timestamptz,
  CHECK((lease_token IS NULL)=(lease_until IS NULL)),
  CHECK((last_synced_at IS NULL)=(cardinality(window_dates)=0))
);
CREATE TABLE public.seo_search_metrics_daily (
  property text NOT NULL DEFAULT 'sc-domain:mock.example.invalid' CHECK(property='sc-domain:mock.example.invalid'),
  source text NOT NULL DEFAULT 'mock' CHECK(source='mock'),
  day date NOT NULL,
  query text NOT NULL CHECK(length(query) BETWEEN 1 AND 100 AND query !~ '[[:cntrl:]]'),
  page text NOT NULL CHECK(length(page)<=300 AND page ~ '^https://mock\.example\.invalid/[^?#[:space:][:cntrl:]]*$'),
  device text NOT NULL CHECK(device IN ('MOBILE','DESKTOP','TABLET')),
  country text NOT NULL CHECK(country ~ '^[a-z]{3}$'),
  clicks bigint NOT NULL CHECK(clicks BETWEEN 0 AND 1000000000),
  impressions bigint NOT NULL CHECK(impressions BETWEEN 0 AND 1000000000 AND impressions>=clicks),
  ctr numeric NOT NULL CHECK(ctr BETWEEN 0 AND 1),
  position numeric NOT NULL CHECK(position BETWEEN 0 AND 1000 AND (impressions=0 OR position>=1)),
  PRIMARY KEY(property,day,query,page,device,country),
  CHECK(abs(ctr-CASE WHEN impressions=0 THEN 0 ELSE clicks::numeric/impressions END)<=0.000001)
);
ALTER TABLE public.seo_search_sync_state ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.seo_search_metrics_daily ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.seo_search_sync_state,public.seo_search_metrics_daily FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.seo_search_sync_state,public.seo_search_metrics_daily TO service_role;

CREATE FUNCTION public.seo_search_read_mock()
RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public AS $$
DECLARE r public.seo_search_sync_state; v_days jsonb;
BEGIN
  SELECT * INTO r FROM public.seo_search_sync_state WHERE property='sc-domain:mock.example.invalid';
  IF NOT FOUND THEN RETURN jsonb_build_object('source','mock','property','sc-domain:mock.example.invalid',
    'version',0,'window','[]'::jsonb,'truncatedDates','[]'::jsonb,'days','[]'::jsonb,
    'lastSyncedAt',NULL,'lastAttemptAt',NULL,'lastError',NULL,'syncing',false); END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('date',d,'rows',(
    SELECT coalesce(jsonb_agg(jsonb_build_object('keys',jsonb_build_array(m.day,m.query,m.page,m.device,m.country),
      'clicks',m.clicks,'impressions',m.impressions,'ctr',m.ctr,'position',m.position)
      ORDER BY m.query,m.page,m.device,m.country),'[]'::jsonb)
    FROM public.seo_search_metrics_daily m WHERE m.property=r.property AND m.day=d
  )) ORDER BY d),'[]'::jsonb) INTO v_days FROM unnest(r.window_dates) d;
  RETURN jsonb_build_object('source','mock','property',r.property,'version',r.version,'window',r.window_dates,
    'truncatedDates',r.truncated_dates,'days',v_days,'lastSyncedAt',r.last_synced_at,
    'lastAttemptAt',r.last_attempt_at,'lastError',r.last_error_code,
    'syncing',coalesce(r.lease_until>statement_timestamp(),false));
END;
$$;
CREATE FUNCTION public.seo_search_begin_mock()
RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,public SET lock_timeout='2s' AS $$
DECLARE r public.seo_search_sync_state; v_now timestamptz:=clock_timestamp();
BEGIN
  INSERT INTO public.seo_search_sync_state(property) VALUES('sc-domain:mock.example.invalid') ON CONFLICT DO NOTHING;
  SELECT * INTO r FROM public.seo_search_sync_state WHERE property='sc-domain:mock.example.invalid' FOR UPDATE;
  IF r.lease_until>v_now THEN RAISE EXCEPTION 'SEARCH_SYNC_BUSY' USING ERRCODE='PT409'; END IF;
  UPDATE public.seo_search_sync_state SET version=version+1,lease_token=gen_random_uuid(),
    lease_until=v_now+interval '120 seconds',last_attempt_at=v_now,last_error_code=NULL
    WHERE property=r.property RETURNING * INTO r;
  RETURN jsonb_build_object('token',r.lease_token,'version',r.version,'startedAt',v_now);
END;
$$;
CREATE FUNCTION public.seo_search_complete_mock(p_token uuid,p_version integer,p_window date[],p_days jsonb,p_truncated date[])
RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,public SET lock_timeout='2s' AS $$
DECLARE r public.seo_search_sync_state; i integer; d jsonb; v_row jsonb; k jsonb;
  v_clicks numeric; v_impressions numeric; v_ctr numeric; v_position numeric;
BEGIN
  SELECT * INTO r FROM public.seo_search_sync_state WHERE property='sc-domain:mock.example.invalid' FOR UPDATE;
  IF NOT FOUND OR r.lease_token IS NULL OR r.lease_token IS DISTINCT FROM p_token OR r.version IS DISTINCT FROM p_version
    OR r.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'SEARCH_SYNC_LEASE_CONFLICT' USING ERRCODE='PT409'; END IF;
  IF p_window IS NULL OR cardinality(p_window)<>14 OR array_lower(p_window,1)<>1 OR p_window[1] IS NULL
    OR jsonb_typeof(p_days) IS DISTINCT FROM 'array' OR jsonb_array_length(p_days)<>14
    OR p_truncated IS NULL OR cardinality(p_truncated)>14 OR NOT p_truncated<@p_window
    OR cardinality(p_truncated)<>(SELECT count(DISTINCT x) FROM unnest(p_truncated) x)
  THEN RAISE EXCEPTION 'INVALID_SEARCH_SNAPSHOT' USING ERRCODE='22023'; END IF;
  -- Derived mock rows for these days are replaced atomically, not source data.
  DELETE FROM public.seo_search_metrics_daily WHERE property=r.property AND day=ANY(p_window);
  FOR i IN 1..14 LOOP
    d:=p_days->(i-1);
    IF p_window[i] IS DISTINCT FROM p_window[1]+(i-1) OR jsonb_typeof(d) IS DISTINCT FROM 'object'
      OR d->>'date' IS DISTINCT FROM p_window[i]::text OR jsonb_typeof(d->'rows') IS DISTINCT FROM 'array'
      OR jsonb_array_length(d->'rows')>200 THEN RAISE EXCEPTION 'INVALID_SEARCH_DAY' USING ERRCODE='22023'; END IF;
    FOR v_row IN SELECT value FROM jsonb_array_elements(d->'rows') LOOP
      k:=v_row->'keys';
      IF jsonb_typeof(v_row) IS DISTINCT FROM 'object' OR jsonb_typeof(k) IS DISTINCT FROM 'array'
        OR jsonb_array_length(k)<>5 OR k->>0 IS DISTINCT FROM p_window[i]::text
        OR EXISTS(SELECT 1 FROM jsonb_array_elements(k) x WHERE jsonb_typeof(x)<>'string')
        OR EXISTS(SELECT 1 FROM unnest(ARRAY['clicks','impressions','ctr','position']) name
          WHERE jsonb_typeof(v_row->name) IS DISTINCT FROM 'number') THEN
        RAISE EXCEPTION 'INVALID_SEARCH_ROW' USING ERRCODE='22023'; END IF;
      v_clicks:=(v_row->>'clicks')::numeric; v_impressions:=(v_row->>'impressions')::numeric;
      v_ctr:=(v_row->>'ctr')::numeric;v_position:=(v_row->>'position')::numeric;
      IF v_clicks<>trunc(v_clicks) OR v_impressions<>trunc(v_impressions) OR btrim(k->>1)=''
        OR length(k->>2)>length('https://mock.example.invalid')+250 THEN
        RAISE EXCEPTION 'INVALID_SEARCH_METRIC' USING ERRCODE='22023'; END IF;
      INSERT INTO public.seo_search_metrics_daily(property,day,query,page,device,country,clicks,impressions,ctr,position)
      VALUES(r.property,p_window[i],k->>1,k->>2,k->>3,k->>4,v_clicks,v_impressions,v_ctr,v_position);
    END LOOP;
  END LOOP;
  UPDATE public.seo_search_sync_state SET window_dates=p_window,truncated_dates=p_truncated,last_synced_at=clock_timestamp(),
    last_error_code=NULL,lease_token=NULL,lease_until=NULL WHERE property=r.property;
  RETURN public.seo_search_read_mock();
END;
$$;
CREATE FUNCTION public.seo_search_fail_mock(p_token uuid,p_version integer,p_code text)
RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,public SET lock_timeout='2s' AS $$
BEGIN
  IF p_code IS NULL OR p_code NOT IN ('INVALID_RESPONSE','UNAVAILABLE','RATE_LIMITED','QUOTA_EXCEEDED','TIMEOUT','REJECTED','CIRCUIT_OPEN','CONCURRENCY_LIMIT','STORAGE_UNAVAILABLE','BLOCKED') THEN
    RAISE EXCEPTION 'INVALID_SEARCH_ERROR_CODE' USING ERRCODE='22023'; END IF;
  UPDATE public.seo_search_sync_state SET lease_token=NULL,lease_until=NULL,last_error_code=p_code
  WHERE property='sc-domain:mock.example.invalid' AND lease_token=p_token AND version=p_version;
  IF NOT FOUND THEN RAISE EXCEPTION 'SEARCH_SYNC_LEASE_CONFLICT' USING ERRCODE='PT409'; END IF;
END;
$$;
REVOKE ALL ON FUNCTION public.seo_search_read_mock(),public.seo_search_begin_mock(),public.seo_search_complete_mock(uuid,integer,date[],jsonb,date[]),public.seo_search_fail_mock(uuid,integer,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.seo_search_read_mock(),public.seo_search_begin_mock(),public.seo_search_complete_mock(uuid,integer,date[],jsonb,date[]),public.seo_search_fail_mock(uuid,integer,text) TO service_role;
COMMIT;

-- ===== 7/8 pagespeed-durable-mock.sql =====
-- First install on TEST DB. Synthetic allowlisted targets only, no PSI transport/key.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
CREATE TABLE public.seo_pagespeed_audit_state (
  target_id text NOT NULL CHECK(target_id IN ('home_vi','home_en','catalog_vi','catalog_en','product_vi','product_en')),
  strategy text NOT NULL CHECK(strategy IN ('mobile','desktop')),
  source text NOT NULL DEFAULT 'mock' CHECK(source='mock'),
  version integer NOT NULL DEFAULT 0 CHECK(version>=0),
  last_attempt_at timestamptz,
  last_error_code text CHECK(last_error_code IN ('INVALID_RESPONSE','UNAVAILABLE','RATE_LIMITED','QUOTA_EXCEEDED','TIMEOUT','REJECTED','CIRCUIT_OPEN','CONCURRENCY_LIMIT','STORAGE_UNAVAILABLE','BLOCKED')),
  lease_token uuid UNIQUE,
  lease_until timestamptz,
  PRIMARY KEY(target_id,strategy),
  CHECK((lease_token IS NULL)=(lease_until IS NULL))
);
CREATE TABLE public.seo_pagespeed_samples (
  target_id text NOT NULL,
  strategy text NOT NULL,
  source text NOT NULL DEFAULT 'mock' CHECK(source='mock'),
  measured_at timestamptz NOT NULL,
  stored_at timestamptz NOT NULL,
  lighthouse_version text NOT NULL CHECK(lighthouse_version ~ '^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}(-mock)?$'),
  performance_score numeric CHECK(performance_score BETWEEN 0 AND 100),
  accessibility_score numeric CHECK(accessibility_score BETWEEN 0 AND 100),
  best_practices_score numeric CHECK(best_practices_score BETWEEN 0 AND 100),
